134		 * Load multiple watchlist labels at once by their IDs.
135		 *
136		 * @param UserIdentity $user
137		 * @param int[] $ids The IDs of the watchlist labels to load.
138		 *
139		 * @return WatchlistLabel[] The labels that were found.
140		 */
141		public function loadByIds( UserIdentity $user, array $ids ): array {
142			$result = $this->dbProvider->getReplicaDatabase()->newSelectQueryBuilder()
143				->select( [ 'wll_id', 'wll_name' ] )
144				->from( self::TABLE_WATCHLIST_LABEL )
145				// It's not necessary to query for the user, but it adds an extra check.
146				->where( [ 'wll_id' => $ids, 'wll_user' => $user->getId() ] )
147				->caller( __METHOD__ )
148				->fetchResultSet();
149	
150			return array_map(
151				static fn ( $row ) => new WatchlistLabel( $user, $row->wll_name, $row->wll_id ),
152				iterator_to_array( $result )
153			);
154		}
