156		/**
157		 * Load a single watchlist label by (normalized) name.
158		 *
159		 * @param UserIdentity $user
160		 * @param string $name The name to search for.
161		 *
162		 * @return ?WatchlistLabel The label, or null if not found.
163		 */
164		public function loadByName( UserIdentity $user, string $name ): ?WatchlistLabel {
165			$select = $this->dbProvider->getReplicaDatabase()->newSelectQueryBuilder();
166			$label = new WatchlistLabel( $user, $name );
167			$result = $select->table( self::TABLE_WATCHLIST_LABEL )
168				->fields( [ 'wll_id', 'wll_name' ] )
169				->where( [ 'wll_user' => $label->getUser()->getId(), 'wll_name' => $label->getName() ] )
170				->caller( __METHOD__ )
171				->fetchRow();
172			if ( $result ) {
173				$label->setId( $result->wll_id );
174				return $label;
175			}
176			return null;
