179		/**
180		 * Get all of a user's watchlist labels.
181		 *
182		 * @param UserIdentity $user
183		 *
184		 * @return WatchlistLabel[] Labels indexed by ID
185		 */
186		public function loadAllForUser( UserIdentity $user ): array {
187			$dbr = $this->dbProvider->getReplicaDatabase();
188			$orderBy = 'wll_name';
189			if ( $dbr->getType() === 'mysql' ) {
190				$orderBy = 'CONVERT(wll_name USING utf8mb4) COLLATE utf8mb4_general_ci';
191			} elseif ( $dbr->getType() === 'sqlite' ) {
192				$orderBy = 'wll_name COLLATE NOCASE';
193			}
194			$select = $dbr->newSelectQueryBuilder();
195			$results = $select->table( self::TABLE_WATCHLIST_LABEL )
196				->fields( [ 'wll_id', 'wll_name' ] )
197				->where( [ 'wll_user' => $user->getId() ] )
198				->orderBy( $orderBy, 'ASC' )
199				->caller( __METHOD__ )
200				->fetchResultSet();
201			$labels = [];
202			foreach ( $results as $result ) {
203				$labels[ (int)$result->wll_id ] = new WatchlistLabel( $user, $result->wll_name, $result->wll_id );
204			}
205			return $labels;
206		}
