407		 * @param UserIdentity $userIdentity
408		 * @param PageReference $target
409		 * @return StatusValue
410		 */
411		public function removeWatchIgnoringRights(
412			UserIdentity $userIdentity,
413			PageReference $target
414		): StatusValue {
415			if ( !$this->isWatchable( $target ) ) {
416				return StatusValue::newFatal( 'watchlistnotwatchable' );
417			}
418	
419			$wikiPage = $this->wikiPageFactory->newFromTitle( $target );
420			$title = $wikiPage->getTitle();
421	
422			$status = Status::newFatal( 'hookaborted' );
423			// TODO broaden the interface on these hooks from WikiPage to PageReference
424			if ( $this->hookRunner->onUnwatchArticle( $userIdentity, $wikiPage, $status ) ) {
425				$status = StatusValue::newGood();
426				$this->watchedItemStore->removeWatch( $userIdentity, $this->getSubjectPage( $title ) );
427				if ( $this->nsInfo->canHaveTalkPage( $title ) ) {
428					$this->watchedItemStore->removeWatch( $userIdentity, $this->getTalkPage( $title ) );
429				}
430				$this->hookRunner->onUnwatchArticleComplete( $userIdentity, $wikiPage );
431			}
432	
433			// eventually user_touched should be factored out of User and this should be replaced
434			$user = $this->userFactory->newFromUserIdentity( $userIdentity );
435			$user->invalidateCache();
436	
437			return $status;
438		}
