472		/**
473		 * Stop watching a page if the user has permission to edit their watchlist.
474		 * Calls the UnwatchArticle and UnwatchArticleComplete hooks.
475		 * @since 1.37
476		 * @param Authority $performer
477		 * @param PageReference $target
478		 * @return StatusValue
479		 */
480		public function removeWatch(
481			Authority $performer,
482			PageReference $target
483		): StatusValue {
484			$status = PermissionStatus::newEmpty();
485			if ( !$performer->isAllowed( 'editmywatchlist', $status ) ) {
486				return $status;
487			}
488	
489			return $this->removeWatchIgnoringRights( $performer->getUser(), $target );
